/* BEGIN js/shared/utils.js */
/* Shared pure utilities. Keep legacy parsing semantics; no DOM or network effects. */
(() => {
  const kc=window.KinballCoach ||= {};
  function escapeHtml(v){
    return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  }
  function matchYoutubeId(raw){
    const value=(raw||'').trim();
    if(/^[\w-]{11}$/.test(value))return value;
    try{
      const u=new URL(value);
      if(u.hostname==='youtu.be')return u.pathname.split('/').filter(Boolean)[0]||'';
      if(u.searchParams.get('v'))return u.searchParams.get('v');
      const parts=u.pathname.split('/').filter(Boolean);
      const i=parts.findIndex(x=>['embed','shorts','live'].includes(x));
      return i>=0?parts[i+1]||'':'';
    }catch{return ''}
  }
  function parseMatchVideoTime(value){
    const raw=String(value||'').trim();
    if(!raw)return 0;
    const parts=raw.split(':').map(x=>Number(x));
    if(parts.some(x=>!Number.isFinite(x)||x<0))return 0;
    if(parts.length===3)return parts[0]*3600+parts[1]*60+parts[2];
    if(parts.length===2)return parts[0]*60+parts[1];
    if(parts.length===1)return parts[0];
    return 0;
  }
  function formatMatchVideoTime(seconds){
    const n=Math.max(0,Number(seconds)||0),s=Math.floor(n),m=Math.floor(s/60),h=Math.floor(m/60);
    const mm=h?String(m%60).padStart(2,'0'):String(m),ss=String(s%60).padStart(2,'0');
    return h?`${h}:${mm}:${ss}`:`${mm}:${ss}`;
  }
  kc.utils=Object.freeze({escapeHtml,escapeAttr:escapeHtml,matchYoutubeId,parseMatchVideoTime,formatMatchVideoTime});
})();
/* END js/shared/utils.js */

/* BEGIN js/shared/context.js */
/* One application context per document. Modules register before page bootstrap. */
(() => {
  const kc=window.KinballCoach ||= {};
  kc.app ||= {};
  kc.policies ||= {};
})();
/* END js/shared/context.js */

/* BEGIN js/shared/data.js */
/* Read services with explicit dependencies. No DOM, cache or startup side effects. */
(() => {
  window.KinballCoach.createDataServices=({db,getUser})=>({
    async profiles(userIds){
      const ids=[...new Set((userIds||[]).filter(Boolean))];
      if(!ids.length)return {};
      const {data,error}=await db.from('user_profiles').select('user_id,first_name').in('user_id',ids);
      if(error)throw error;
      const map={};
      (data||[]).forEach(p=>map[p.user_id]=p.first_name);
      return map;
    },
    async myProfile(){
      const user=getUser();
      if(!user)return null;
      const {data,error}=await db.from('user_profiles').select('first_name').eq('user_id',user.id).maybeSingle();
      if(error)throw error;
      return data||null;
    },
    async myGroups(){
      const {data,error}=await db.from('coaching_group_coaches')
        .select('role,group:coaching_groups!coaching_group_coaches_group_id_fkey(id,name,club,invite_code)')
        .eq('user_id',getUser().id)
        .order('joined_at',{ascending:true});
      if(error)throw error;
      return (data||[]).filter(x=>x.group).map(x=>({...x.group,role:x.role}));
    },
    async groupPlayers(groupId){
      if(!groupId)return [];
      const {data,error}=await db.from('coaching_group_players')
        .select('player_id,active,preferred_role,stats_access,player:players!coaching_group_players_player_id_fkey(id,display_name)')
        .eq('group_id',groupId).eq('active',true);
      if(error)throw error;
      return (data||[]).filter(x=>x.player).map(x=>({...x.player,preferred_role:x.preferred_role||'AP',stats_access:x.stats_access||'personal'})).sort((a,b)=>a.display_name.localeCompare(b.display_name,'fr'));
    },
    async playerAccess(){
      const {data,error}=await db.rpc('get_my_player_access');
      if(error)throw error;
      return data||[];
    },
    async matchTypes(){
      const {data,error}=await db.from('match_types')
        .select('id,name,slug,active,is_native,created_by,created_at,updated_by,updated_at')
        .order('is_native',{ascending:false}).order('name');
      if(error)throw error;
      return data||[];
    },
    async exerciseCategories(){
      const {data,error}=await db.from('exercise_categories')
        .select('id,name,slug,active,is_native,is_dual_focus,created_by,created_at,updated_by,updated_at')
        .order('is_native',{ascending:false}).order('name');
      if(error)throw error;
      return data||[];
    },
    async trainingSessions(groupId){
      const {data,error}=await db.from('training_sessions')
        .select('id,trained_on,label,theme')
        .eq('group_id',groupId).order('trained_on',{ascending:true});
      if(error)throw error;
      return data||[];
    },
    async trainingResults(sessionIds){
      if(!sessionIds.length)return {attendance:[],sessionExercises:[],results:[]};
      const responses=await Promise.all([
        db.from('training_attendance').select('session_id,player_id,present').in('session_id',sessionIds),
        db.from('training_session_exercises')
          .select('session_id,exercise_id,focus,position,exercise:exercises!training_session_exercises_exercise_id_fkey(id,name,category,category_id,copied_from_exercise_id,measurement_type)')
          .in('session_id',sessionIds),
        db.from('training_results').select('id,session_id,exercise_id,player_id,successes,attempts,numeric_value,note,created_at').in('session_id',sessionIds)
      ]);
      for(const response of responses)if(response.error)throw response.error;
      return {attendance:responses[0].data||[],sessionExercises:responses[1].data||[],results:responses[2].data||[]};
    },
    async groupSelections(groupId,{includeArchived=false}={}){
      if(!groupId)return [];
      let query=db.from('coaching_group_selections')
        .select('id,group_id,name,selection_type,starts_on,ends_on,archived,created_at,updated_at')
        .eq('group_id',groupId)
        .order('created_at',{ascending:true});
      if(!includeArchived)query=query.eq('archived',false);
      const {data:selections,error}=await query;
      if(error)throw error;
      const ids=(selections||[]).map(s=>s.id);
      let members=[];
      if(ids.length){
        const {data,error}=await db.from('coaching_group_selection_players')
          .select('selection_id,player_id').in('selection_id',ids);
        if(error)throw error;
        members=data||[];
      }
      const bySelection=new Map();
      members.forEach(row=>{if(!bySelection.has(row.selection_id))bySelection.set(row.selection_id,[]);bySelection.get(row.selection_id).push(row.player_id)});
      return (selections||[]).map(s=>({...s,player_ids:bySelection.get(s.id)||[]}));
    }
  });
})();
/* END js/shared/data.js */

/* BEGIN js/shared/match-data.js */
/* Match dataset assembly. Explicit client, no DOM or mutable page state. */
window.KinballCoach.createMatchDataService = (db) => async function loadMatchAnalysisDataset(matchIds){
  const unique=[...new Set((matchIds||[]).filter(Boolean))];
  if(!unique.length)throw new Error('Aucun match à analyser.');
  const {data:matches,error:me}=await db.from('matches')
    .select('id,label,played_on,group_id,match_type_id,team_id,opponent_team_1_id,opponent_team_2_id,match_type:match_types!matches_match_type_id_fkey(name),group:coaching_groups!matches_group_id_fkey(name),followed_team:teams!matches_team_id_fkey(name),opponent1:teams!matches_opponent_team_1_id_fkey(id,name),opponent2:teams!matches_opponent_team_2_id_fkey(id,name)')
    .in('id',unique);
  if(me)throw me;

  const {data:events,error:ee}=await db.from('match_events')
    .select('*')
    .in('match_id',unique)
    .order('sequence_no',{ascending:true});
  if(ee)throw ee;

  const ids=(events||[]).map(e=>e.id);
  let attributions=[],lineups=[];
  if(ids.length){
    const [a,l]=await Promise.all([
      db.from('match_event_attributions').select('event_id,player_id,players!match_event_attributions_player_id_fkey(display_name)').in('event_id',ids),
      db.from('match_event_lineup').select('event_id,player_id,players!match_event_lineup_player_id_fkey(display_name)').in('event_id',ids)
    ]);
    if(a.error)throw a.error;
    if(l.error)throw l.error;
    attributions=a.data||[];
    lineups=l.data||[];
  }

  const eventPlayerIds=[...new Set((events||[]).map(e=>e.player_id).filter(Boolean))];
  let eventPlayerMap={};
  if(eventPlayerIds.length){
    const {data,error}=await db.from('players').select('id,display_name').in('id',eventPlayerIds);
    if(error)throw error;
    eventPlayerMap=Object.fromEntries((data||[]).map(p=>[p.id,p.display_name]));
  }

  const {data:matchPlayers,error:mpe}=await db.from('match_players')
    .select('match_id,player_id,players!match_players_player_id_fkey(display_name)')
    .in('match_id',unique);
  if(mpe)throw mpe;

  const attrMap={},lineMap={};
  attributions.forEach(a=>{
    const n=a.players?.display_name;
    if(n)(attrMap[a.event_id]??=[]).push(n);
  });
  lineups.forEach(l=>{
    const n=l.players?.display_name;
    if(n)(lineMap[l.event_id]??=[]).push(n);
  });

  const matchMap=Object.fromEntries((matches||[]).map(m=>[m.id,m]));
  const normalized=(events||[]).map(e=>{
    const match=matchMap[e.match_id]||null;
    let opponent_name=null;
    if(e.opponent_team_id&&match){
      if(e.opponent_team_id===match.opponent_team_1_id||e.opponent_team_id===match.opponent1?.id)opponent_name=match.opponent1?.name||null;
      else if(e.opponent_team_id===match.opponent_team_2_id||e.opponent_team_id===match.opponent2?.id)opponent_name=match.opponent2?.name||null;
    }
    return {
      ...e,
      match,
      opponent_name,
      attributed_names:attrMap[e.id]||[],
      lineup_names:lineMap[e.id]||[],
      player_name:e.player_id?eventPlayerMap[e.player_id]||null:null
    };
  });

  const playerNames=[...new Set([
    ...(matchPlayers||[]).map(p=>p.players?.display_name),
    ...attributions.map(a=>a.players?.display_name),
    ...lineups.map(l=>l.players?.display_name),
    ...Object.values(eventPlayerMap)
  ].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr'));

  return {matchIds:unique,matches:matches||[],events:normalized,players:playerNames};
};
/* END js/shared/match-data.js */

/* BEGIN js/shared/calculations.js */
/* Pure calculations. Reference and sorting policy are explicit parameters. */
(() => {
 const calc={};
calc.analysisSemanticType = function analysisSemanticType(e){
  if(e.action_type==='attaque')return 'attack';
  if(e.action_type==='defense')return 'defense';
  if(e.action_type==='faute'&&e.fault_type==='Défensive illégale')return 'defense';
  return 'attack';
};

calc.analysisOutcome = function analysisOutcome(e){
  const type=calc.analysisSemanticType(e);
  if(type==='attack'){
    if(e.action_type==='faute')return 'Faute attaque';
    return e.result||'Non précisé';
  }
  if(e.action_type==='faute'&&e.fault_type==='Défensive illégale')return 'Défensive illégale';
  return e.result||'Non précisé';
};

calc.analysisContextKey = function analysisContextKey(e){
  if(e.family==='centre')return 'centre';
  if(e.family==='gel')return 'gel';
  if(e.family==='remise')return 'remise_'+(e.restart_location||'centre');
  return e.family||'autre';
};

calc.analysisContextLabel = function analysisContextLabel(key){
  return ({
    centre:'Centre',
    remise:'Remise en jeu',
    remise_centre:'Remise · Centre',
    remise_ligne:'Remise · Ligne',
    remise_coin:'Remise · Coin',
    gel:'Gel'
  })[key]||key||'Autre';
};

calc.analysisEventPeople = function analysisEventPeople(e){
  const names=[...(e.attributed_names||[])];
  if(!names.length&&e.player_name)names.push(e.player_name);
  return [...new Set(names.filter(Boolean))];
};

calc.analysisIsFault = function analysisIsFault(e){
  return e.action_type==='faute';
};

calc.analysisPct = function analysisPct(n,d){
  return d?Math.round(100*n/d):null;
};

calc.analysisPctLabel = function analysisPctLabel(n,d){
  const numerator=Number(n)||0;
  const denominator=Number(d)||0;
  const p=calc.analysisPct(numerator,denominator);
  return `${p==null?'—':p+' %'} (${numerator}/${denominator})`;
};

calc.analysisPeriodSort = function analysisPeriodSort(a,b){
  const na=parseInt(String(a).replace(/\D/g,''),10);
  const nb=parseInt(String(b).replace(/\D/g,''),10);
  if(Number.isFinite(na)&&Number.isFinite(nb))return na-nb;
  return String(a).localeCompare(String(b),'fr');
};

calc.analysisStats = function analysisStats(events){
  const attacks=events.filter(e=>calc.analysisSemanticType(e)==='attack');
  const defenses=events.filter(e=>calc.analysisSemanticType(e)==='defense');
  const attack={
    total:attacks.length,
    points:attacks.filter(e=>['Point marqué','Défensive illégale'].includes(calc.analysisOutcome(e))).length,
    faults:attacks.filter(e=>calc.analysisOutcome(e)==='Faute attaque').length,
    defended:attacks.filter(e=>calc.analysisOutcome(e)==='Ballon défendu').length,
    illegal:attacks.filter(e=>calc.analysisOutcome(e)==='Défensive illégale').length
  };
  const defenseEscaped=defenses.filter(e=>calc.analysisOutcome(e)==='Échappé').length;
  const defenseIllegal=defenses.filter(e=>calc.analysisOutcome(e)==='Défensive illégale').length;
  const defense={
    total:defenses.length,
    defended:defenses.filter(e=>calc.analysisOutcome(e)==='Ballon défendu').length,
    escaped:defenseEscaped,
    illegal:defenseIllegal,
    points:defenseEscaped+defenseIllegal,
    opponentFaults:defenses.filter(e=>calc.analysisOutcome(e)==='Faute de l’adversaire').length
  };
  return {attack,defense};
};

calc.analysisDefenseSuccesses = function analysisDefenseSuccesses(stats){
  return (stats?.defended||0)+(stats?.opponentFaults||0);
};

calc.analysisDefensePctLabel = function analysisDefensePctLabel(stats){
  return calc.analysisPctLabel(calc.analysisDefenseSuccesses(stats),stats?.total||0);
};

calc.analysisOpponentAttackPctLabel = function analysisOpponentAttackPctLabel(stats){
  return calc.analysisPctLabel(stats?.points||0,stats?.total||0);
};

calc.analysisAttackZoneLabel = function analysisAttackZoneLabel(zone){
  const z=({E1:'A1',E2:'P',E3:'A2'}[zone]||zone||'Non précisée');
  return z;
};

calc.analysisDefenseZoneGroup = function analysisDefenseZoneGroup(zone){
  if(zone==='R'||zone==='RE')return 'R / RE';
  if(['EE','A1','P','A2','E1','E2','E3'].includes(zone))return 'EE / reste';
  return 'Non précisée';
};

calc.groupPopulationFromName = function groupPopulationFromName(name){
  const t=String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if(/\b(feminin|feminine|femmes|femme|edf f)\b/.test(t))return 'F';
  if(/\b(hommes|homme|masculin|masculine|edf h)\b/.test(t))return 'H';
  return null;
};

calc.offensiveContextFromEvent = function offensiveContextFromEvent(e){
  if(e.family==='centre')return 'game_center';
  if(e.family!=='remise')return null;
  if(e.restart_location==='centre')return 'restart_center';
  if(e.restart_location==='ligne')return 'restart_line';
  if(e.restart_location==='coin')return 'restart_corner';
  return null;
};

calc.offensiveActualValue = function offensiveActualValue(outcome){
  if(outcome==='Point marqué'||outcome==='Défensive illégale')return 1;
  if(outcome==='Ballon défendu')return 0;
  if(outcome==='Faute attaque')return -1;
  return null;
};

calc.playerOffensiveImpact = function playerOffensiveImpact(events,playerName,scope='all',reference){
  const ref=reference;
  const out={name:playerName,total:0,points:0,defended:0,faults:0,expectedPoints:0,expectedFaults:0,actualValue:0,expectedValue:0,creation:0,safety:0,creation100:null,safety100:null,impact:0,impact100:null};
  if(!ref)return out;
  events.forEach(e=>{
    if(calc.analysisSemanticType(e)!=='attack')return;
    const people=calc.analysisEventPeople(e);
    if(people.length!==1||people[0]!==playerName)return;
    const context=calc.offensiveContextFromEvent(e);
    if(scope==='center'&&context!=='game_center')return;
    if(scope==='restart'&&!['restart_center','restart_line','restart_corner'].includes(context))return;
    if(scope==='restart_center'&&context!=='restart_center')return;
    if(scope==='restart_line'&&context!=='restart_line')return;
    if(scope==='restart_corner'&&context!=='restart_corner')return;
    const r=ref.contexts[context];
    if(!context||!r||!r.total)return;
    const outcome=calc.analysisOutcome(e);
    const value=calc.offensiveActualValue(outcome);
    if(value==null)return;
    out.total++;
    if(outcome==='Point marqué'||outcome==='Défensive illégale')out.points++;
    else if(outcome==='Ballon défendu')out.defended++;
    else if(outcome==='Faute attaque')out.faults++;
    out.expectedPoints+=r.p;
    out.expectedFaults+=r.q;
    out.actualValue+=value;
    out.expectedValue+=r.mu;
  });
  out.pointRate=out.total?100*out.points/out.total:null;
  out.faultRate=out.total?100*out.faults/out.total:null;
  out.expectedPointRate=out.total?100*out.expectedPoints/out.total:null;
  out.expectedFaultRate=out.total?100*out.expectedFaults/out.total:null;
  out.creation=out.points-out.expectedPoints;
  out.safety=out.expectedFaults-out.faults;
  out.creation100=out.total?100*out.creation/out.total:null;
  out.safety100=out.total?100*out.safety/out.total:null;
  out.impact=out.creation+out.safety;
  out.impact100=out.total?100*out.impact/out.total:null;
  return out;
};

calc.signed1 = function signed1(v){
  if(v==null||!Number.isFinite(v))return '—';
  const rounded=Math.round(v*10)/10;
  return `${rounded>0?'+':''}${rounded.toFixed(1).replace('.',',')}`;
};

calc.pct1 = function pct1(v){
  if(v==null||!Number.isFinite(v))return '—';
  return `${(Math.round(v*10)/10).toFixed(1).replace('.',',')} %`;
};

calc.statsImpactSortRows = function statsImpactSortRows(rows,options={}){
  const field=options.field||'impact100';
  const dir=options.direction||'desc';
  const sorted=[...(rows||[])];
  const getVal=row=>{
    switch(field){
      case 'name': return String(row.name||'');
      case 'total': return row.total;
      case 'pointRate': return row.pointRate;
      case 'faultRate': return row.faultRate;
      case 'creation100': return row.creation100;
      case 'safety100': return row.safety100;
      case 'impact100':
      default: return row.impact100;
    }
  };
  sorted.sort((a,b)=>{
    const av=getVal(a), bv=getVal(b);
    if(field==='name'){
      const cmp=String(av).localeCompare(String(bv),'fr');
      return dir==='asc'?cmp:-cmp;
    }
    const aMissing=av==null||!Number.isFinite(av), bMissing=bv==null||!Number.isFinite(bv);
    if(aMissing&&bMissing)return String(a.name||'').localeCompare(String(b.name||''),'fr');
    if(aMissing)return 1;
    if(bMissing)return -1;
    const cmp=av===bv?0:(av<bv?-1:1);
    if(cmp!==0)return dir==='asc'?cmp:-cmp;
    return String(a.name||'').localeCompare(String(b.name||''),'fr');
  });
  return sorted;
};

calc.impactClass = function impactClass(v){
  if(v>0.05)return 'analysisImpactPositive';
  if(v<-0.05)return 'analysisImpactNegative';
  return 'analysisImpactNeutral';
};

calc.statsImpactQuantile = function statsImpactQuantile(values,q){
  const arr=(values||[]).filter(Number.isFinite).sort((a,b)=>a-b);
  if(!arr.length)return null;
  if(arr.length===1)return arr[0];
  const pos=(arr.length-1)*q;
  const lo=Math.floor(pos),hi=Math.ceil(pos);
  return lo===hi?arr[lo]:arr[lo]+(arr[hi]-arr[lo])*(pos-lo);
};

calc.statsImpactAnonymousBenchmark = function statsImpactAnonymousBenchmark(rows,key){
  const vals=(rows||[]).map(x=>x[key]).filter(Number.isFinite);
  if(!vals.length)return null;
  return {
    mean:vals.reduce((sum,v)=>sum+v,0)/vals.length,
    count:vals.length
  };
};
 window.KinballCoach.calculations=Object.freeze(calc);
})();
